// commands/docs.rs — `tond docs cli` (hidden): the CLI reference as Markdown
//
// Walks the clap command tree (every visible command, argument and option,
// with defaults, possible values and environment variables) and prints
// docs/content/reference/cli.md, so the published reference is generated
// from the code and can't drift: `just docs-gen` rewrites the file and a test
// fails when the committed copy is stale.

use std::fmt::Write;

use clap::{Arg, ArgAction, Command};

const INTRO: &str = r#"# CLI

<!-- Generated by `tond docs cli` from the CLI's own definitions (run `just docs-gen`). Do not edit by hand. -->

`tond` is the command-line interface to a Tond server. It ships with every install (`/usr/local/bin/tond`) and in every release tarball.

**On the server**, run it as root: it talks to tond-server over the root-only Unix socket `/opt/tond/data/tond.sock` and needs no credentials.

**From anywhere else** (your laptop, CI), pass the server's URL and an [API token](/concepts/access): `--server https://tond.example.com --token tond_pat_…`, or set `TOND_SERVER` and `TOND_TOKEN`. What the token may do depends on its scopes.

Every command prints `--help`. Exit codes are described in [Exit codes](/reference/exit-codes)."#;

/// The whole reference page.
pub fn cli_markdown(root: &Command) -> String {
    let mut root = root.clone();
    root.build();
    let mut out = String::from(INTRO);
    out.push_str("\n\n## Global options\n\nThese work with every command.\n\n");
    let globals: Vec<&Arg> = root
        .get_arguments()
        .filter(|a| !a.is_hide_set() && a.is_global_set())
        .collect();
    out.push_str(&options_table(&globals));
    for sub in visible_subcommands(&root) {
        write_command(&mut out, sub, &format!("tond {}", sub.get_name()), 2);
    }
    out.truncate(out.trim_end().len());
    out.push('\n');
    out
}

fn visible_subcommands(cmd: &Command) -> Vec<&Command> {
    cmd.get_subcommands()
        .filter(|c| !c.is_hide_set() && c.get_name() != "help")
        .collect()
}

fn text(s: Option<&clap::builder::StyledStr>) -> Option<String> {
    s.map(|s| s.to_string().trim().to_string())
        .filter(|s| !s.is_empty())
}

fn write_command(out: &mut String, cmd: &Command, path: &str, depth: usize) {
    let hashes = "#".repeat(depth.min(4));
    out.truncate(out.trim_end().len());
    let _ = write!(out, "\n\n{hashes} {path}\n\n");
    if let Some(about) = text(cmd.get_long_about()).or_else(|| text(cmd.get_about())) {
        out.push_str(&about);
        out.push_str("\n\n");
    }
    let subs = visible_subcommands(cmd);
    let args: Vec<&Arg> = cmd
        .get_arguments()
        .filter(|a| !a.is_hide_set() && !a.is_global_set())
        .filter(|a| !matches!(a.get_id().as_str(), "help" | "version"))
        .collect();
    let positionals: Vec<&Arg> = args.iter().copied().filter(|a| a.is_positional()).collect();
    let options: Vec<&Arg> = args
        .iter()
        .copied()
        .filter(|a| !a.is_positional())
        .collect();

    let _ = write!(
        out,
        "```text\n{}\n```\n\n",
        usage(cmd, path, &positionals, &options, &subs)
    );

    if !positionals.is_empty() {
        out.push_str("| Argument | Description |\n| --- | --- |\n");
        for a in &positionals {
            let name = a
                .get_value_names()
                .and_then(|v| v.first())
                .map(|v| v.to_string())
                .unwrap_or_else(|| a.get_id().to_string().to_uppercase());
            let _ = writeln!(
                out,
                "| `{}` | {} |",
                if a.is_required_set() {
                    format!("<{name}>")
                } else {
                    format!("[{name}]")
                },
                describe(a)
            );
        }
        out.push('\n');
    }
    if !options.is_empty() {
        out.push_str(&options_table(&options));
    }
    if !subs.is_empty() {
        out.push_str("| Command | Description |\n| --- | --- |\n");
        for sub in &subs {
            let _ = writeln!(
                out,
                "| `{} {}` | {} |",
                path,
                sub.get_name(),
                cell(&text(sub.get_about()).unwrap_or_default())
            );
        }
        out.push('\n');
        for sub in subs {
            write_command(out, sub, &format!("{path} {}", sub.get_name()), depth + 1);
        }
    }
}

fn usage(
    cmd: &Command,
    path: &str,
    positionals: &[&Arg],
    options: &[&Arg],
    subs: &[&Command],
) -> String {
    let mut parts = vec![path.to_string()];
    if !options.is_empty() {
        parts.push("[OPTIONS]".to_string());
    }
    for a in positionals {
        let name = a
            .get_value_names()
            .and_then(|v| v.first())
            .map(|v| v.to_string())
            .unwrap_or_else(|| a.get_id().to_string().to_uppercase());
        let many = matches!(a.get_action(), ArgAction::Append)
            || a.get_num_args().is_some_and(|n| n.max_values() > 1);
        let name = if many { format!("{name}...") } else { name };
        parts.push(if a.is_required_set() {
            format!("<{name}>")
        } else {
            format!("[{name}]")
        });
    }
    if !subs.is_empty() {
        parts.push(if cmd.is_subcommand_required_set() {
            "<COMMAND>".to_string()
        } else {
            "[COMMAND]".to_string()
        });
    }
    parts.join(" ")
}

fn flag_label(a: &Arg) -> String {
    let mut names = Vec::new();
    if let Some(s) = a.get_short() {
        names.push(format!("-{s}"));
    }
    if let Some(l) = a.get_long() {
        names.push(format!("--{l}"));
    }
    let mut label = names.join(", ");
    let takes_value = a.get_num_args().is_some_and(|n| n.takes_values())
        && !matches!(
            a.get_action(),
            ArgAction::SetTrue | ArgAction::SetFalse | ArgAction::Count
        );
    if takes_value {
        let value = a
            .get_value_names()
            .and_then(|v| v.first())
            .map(|v| v.to_string())
            .unwrap_or_else(|| a.get_id().to_string().to_uppercase());
        let _ = write!(label, " <{value}>");
    }
    label
}

fn options_table(args: &[&Arg]) -> String {
    let mut out = String::from("| Option | Description |\n| --- | --- |\n");
    for a in args {
        let _ = writeln!(out, "| `{}` | {} |", flag_label(a), describe(a));
    }
    out.push('\n');
    out
}

fn describe(a: &Arg) -> String {
    let mut parts = Vec::new();
    if let Some(help) = text(a.get_long_help()).or_else(|| text(a.get_help())) {
        let mut help = cell(&help);
        if !help.ends_with(['.', '!', '?']) {
            help.push('.');
        }
        parts.push(help);
    }
    if a.is_required_set() && !a.is_positional() {
        parts.push("Required.".to_string());
    }
    let possible: Vec<String> = a
        .get_possible_values()
        .iter()
        .filter(|v| !v.is_hide_set())
        .map(|v| format!("`{}`", v.get_name()))
        .collect();
    let is_flag = matches!(a.get_action(), ArgAction::SetTrue | ArgAction::SetFalse);
    if !possible.is_empty() && !is_flag {
        parts.push(format!("One of {}.", possible.join(", ")));
    }
    let defaults: Vec<String> = a
        .get_default_values()
        .iter()
        .map(|v| v.to_string_lossy().into_owned())
        .collect();
    if !defaults.is_empty() && !is_flag {
        parts.push(format!("Default: `{}`.", defaults.join(",")));
    }
    if let Some(env) = a.get_env() {
        parts.push(format!("Env: `{}`.", env.to_string_lossy()));
    }
    parts.join(" ")
}

/// Text safe inside a Markdown table cell.
fn cell(s: &str) -> String {
    s.replace('|', "\\|")
        .split('\n')
        .map(str::trim)
        .filter(|l| !l.is_empty())
        .collect::<Vec<_>>()
        .join(" ")
}

#[cfg(test)]
mod tests {
    use super::*;
    use clap::{Parser, Subcommand};

    #[derive(Parser)]
    #[command(name = "tond")]
    struct Demo {
        /// Server URL
        #[arg(long, global = true, env = "TOND_SERVER")]
        server: Option<String>,
        #[command(subcommand)]
        command: DemoCommand,
    }

    #[derive(Subcommand)]
    enum DemoCommand {
        /// Manage apps
        Apps {
            #[command(subcommand)]
            action: DemoApps,
        },
        #[command(hide = true)]
        Secret,
    }

    #[derive(Subcommand)]
    enum DemoApps {
        /// Create an app | with a pipe
        Create {
            /// App name
            name: String,
            /// Port
            #[arg(long, default_value = "3000")]
            port: u16,
            /// Kind
            #[arg(long, value_parser = ["web", "worker"])]
            kind: Option<String>,
            /// Skip prompts
            #[arg(short, long)]
            yes: bool,
            #[arg(long, hide = true)]
            internal: bool,
        },
    }

    #[test]
    fn renders_commands_options_defaults_and_hides_hidden_ones() {
        use clap::CommandFactory;
        let md = cli_markdown(&Demo::command());
        assert!(
            md.contains("| `--server <SERVER>` | Server URL. Env: `TOND_SERVER`. |"),
            "{md}"
        );
        assert!(md.contains("## tond apps\n\nManage apps"), "{md}");
        assert!(md.contains("### tond apps create"), "{md}");
        assert!(md.contains("tond apps create [OPTIONS] <NAME>"), "{md}");
        assert!(md.contains("| `<NAME>` | App name. |"), "{md}");
        assert!(
            md.contains("| `--port <PORT>` | Port. Default: `3000`. |"),
            "{md}"
        );
        assert!(md.contains("One of `web`, `worker`."), "{md}");
        assert!(md.contains("| `-y, --yes` | Skip prompts. |"), "{md}");
        assert!(md.contains("Create an app \\| with a pipe"), "{md}");
        assert!(!md.contains("secret"), "{md}");
        assert!(!md.contains("internal"), "{md}");
    }

    /// docs/content/reference/cli.md must be what the CLI generates.
    #[test]
    fn the_published_cli_reference_is_up_to_date() {
        use clap::CommandFactory;
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../docs/content/reference/cli.md"
        );
        let committed = std::fs::read_to_string(path).unwrap_or_default();
        let generated = cli_markdown(&crate::Cli::command());
        assert!(
            committed == generated,
            "docs/content/reference/cli.md is out of date with the CLI. Regenerate it: just docs-gen"
        );
    }
}
